    function Assert-HyleTypedGatingFile($hyleTypedGatingRow) {
        $hyleTypedGatingFull = [System.IO.Path]::GetFullPath($hyleTypedGatingRow.Path)
        $hyleTypedGatingResolved = (Resolve-Path -LiteralPath $hyleTypedGatingRow.Path).Path
        if (-not $hyleTypedGatingResolved.Equals($hyleTypedGatingFull, [System.StringComparison]::OrdinalIgnoreCase)) { throw "Resolved path changed: $hyleTypedGatingFull" }
        $hyleTypedGatingFile = Get-Item -LiteralPath $hyleTypedGatingResolved -Force
        if ($hyleTypedGatingFile.PSIsContainer -or ($hyleTypedGatingFile.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) { throw "Expected ordinary file: $hyleTypedGatingResolved" }
        if ($hyleTypedGatingFile.Length -ne $hyleTypedGatingRow.Bytes) { throw "File size changed: $hyleTypedGatingResolved" }
        if ((Get-FileHash -LiteralPath $hyleTypedGatingResolved -Algorithm SHA256).Hash -ne $hyleTypedGatingRow.SHA256) { throw "File hash changed: $hyleTypedGatingResolved" }
    }
    # Verify publications, retained baselines/vectors, and EVERY target before any deletion.
    foreach ($hyleTypedGatingRow in $hyleTypedGatingPublications) { Assert-HyleTypedGatingFile $hyleTypedGatingRow }
    foreach ($hyleTypedGatingRow in $hyleTypedGatingProtectedChecks) { Assert-HyleTypedGatingFile $hyleTypedGatingRow }
    $hyleTypedGatingSeen = @{}
    foreach ($hyleTypedGatingRow in $hyleTypedGatingTargets) {
        $hyleTypedGatingPath = [System.IO.Path]::GetFullPath($hyleTypedGatingRow.Path)
        if ($hyleTypedGatingSeen.ContainsKey($hyleTypedGatingPath)) { throw "Duplicate target: $hyleTypedGatingPath" }
        $hyleTypedGatingSeen[$hyleTypedGatingPath] = $true
        $hyleTypedGatingInside = $false
        foreach ($hyleTypedGatingFolder in $hyleTypedGatingAllowed) {
            if ($hyleTypedGatingPath.StartsWith($hyleTypedGatingFolder.TrimEnd('\') + '\', [System.StringComparison]::OrdinalIgnoreCase)) { $hyleTypedGatingInside = $true }
        }
        if (-not $hyleTypedGatingInside) { throw "Target outside exact batch directories: $hyleTypedGatingPath" }
        if ($hyleTypedGatingProtectedPaths -contains $hyleTypedGatingPath) { throw "Protected input: $hyleTypedGatingPath" }
        $hyleTypedGatingParent = [System.IO.DirectoryInfo]::new([System.IO.Path]::GetDirectoryName($hyleTypedGatingPath))
        while ($null -ne $hyleTypedGatingParent -and -not $hyleTypedGatingParent.FullName.Equals($hyleTypedGatingWorkspace, [System.StringComparison]::OrdinalIgnoreCase)) {
            if ($hyleTypedGatingParent.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { throw "Reparse directory: $($hyleTypedGatingParent.FullName)" }
            $hyleTypedGatingParent = $hyleTypedGatingParent.Parent
        }
